Layer.GoOffMessageCommand:
%function(self)
			self:bounceend(0.3);
				if Choice3Selected then 
					self:x(0); 
					self:y(0); 
					self:diffuse(1,1,1,1);
					self:glowblink();
					self:effectperiod(0.2)
					self:zoom(1);
					self:zoomx(0.95)
					self:sleep(0.5)
					self:accelerate(0.3)
					self:x(-1000)
				else
					self:x(0);
					self:y(0);
					self:z(0);
					self:zoom(0);
				end
				self:sleep(5)
			end

%function(self)
			self:bounceend(0.3);
				if Choice3Selected then 
					self:sleep(0.5)
					self:accelerate(0.3)
					self:x(3000)
					self:z(300);
				else
					self:x(0);
					self:y(0);
					self:z(0);
					self:zoom(0);
				end
				self:sleep(5)
			end
